"""Labels for samples."""


def label_samples(names, samples):
    """Return (lookup, lines): a name -> dose dict and one 'name: dose' line per sample."""
    pairs = zip(names, (x.dose for x in samples))
    lookup = dict(pairs)
    lines = ["%s: %s" % (name, value) for name, value in pairs]
    return lookup, lines


def name_list(names):
    """Return the names joined by commas."""
    return ", ".join(names)


def largest_dose(samples):
    """Return the largest dose, or None when there are no samples."""
    values = [x.dose for x in samples]
    return max(values) if values else None


def group_by_batch(samples):
    """Return a dict from batch to the list of samples with that batch."""
    groups = {}
    for x in samples:
        groups.setdefault(x.batch, []).append(x)
    return groups

