from samples import load_samples, ROWS
from captions import label_samples

NAMES = ["n%d" % i for i in range(len(ROWS))]


def test_lines_present():
    lookup, lines = label_samples(NAMES, load_samples())
    assert len(lines) == len(ROWS)


def test_line_text():
    lookup, lines = label_samples(NAMES, list(load_samples()))
    assert lines[0] == "n0: %s" % ROWS[0][1] and lines[-1] == "n%d: %s" % (len(ROWS) - 1, ROWS[-1][1])


def test_lookup_complete():
    lookup, lines = label_samples(NAMES, load_samples())
    assert lookup == {"n%d" % i: v for i, (_, v) in enumerate(ROWS)}


def test_no_names():
    assert label_samples([], load_samples()) == ({}, [])
